begin;
create extension if not exists pgtap with schema extensions;
set search_path=public,extensions;
select no_plan();
insert into auth.users(id,email,email_confirmed_at) values('11111111-1111-4111-8111-111111111111','solver@example.com',now()),('22222222-2222-4222-8222-222222222222','other@example.com',now()),('33333333-3333-4333-8333-333333333333','abid.ibn.ashraf@gmail.com',now());
insert into public.profiles(id,username) values('11111111-1111-4111-8111-111111111111','Solver'),('22222222-2222-4222-8222-222222222222','Other'),('33333333-3333-4333-8333-333333333333','Owner');
create temp table results(name text primary key,result jsonb);grant all on results to authenticated,anon;
-- An old timer-only solve is the fastest/trimmed member of an otherwise online window.
insert into public.attempts(user_id,session_id,started_at,completed_at,ms,dnf,recording_hash)
 select '11111111-1111-4111-8111-111111111111','aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa',now()-(6-n)*interval '1 second',now(),n*10,false,case when n=1 then null else public.store_recording(jsonb_build_object('format','fto-replay-v1','size',3,'complete',true,'solveMs',n*10,'events','[]'::jsonb),true) end from generate_series(1,4) n;
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
insert into results values('finish',public.record_online_attempt(public.begin_attempt('aaaaaaaa-aaaa-4aaa-8aaa-aaaaaaaaaaaa'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":50,"events":[]}'));
select is((select count(*)::integer from results r cross join lateral jsonb_array_elements(result->'candidates') c where name='finish' and c->>'metric'='ao5'),0,'A missing recording blocks ao5 even when that solve would be trimmed');
select is((select (result->'candidates'->0->>'evidence_complete')::boolean from results where name='finish'),true,'Complete single candidates advertise verified evidence availability');
set local role postgres;
insert into public.submissions(id,user_id,metric,ms,status,evidence_refs) select '44444444-4444-4444-8444-444444444444','11111111-1111-4111-8111-111111111111','ao5',30,'draft',jsonb_agg(jsonb_build_object('ms',ms,'dnf',dnf,'recording_hash',recording_hash) order by started_at) from public.attempts;
set local role authenticated;
select is((select count(*)::integer from jsonb_array_elements(public.my_leaderboard_candidates()) c where c->>'metric'='ao5'),0,'Legacy draft averages with missing evidence stay hidden');
select throws_ok($$select public.submit_leaderboard('44444444-4444-4444-8444-444444444444')$$,'P0001','One or more recordings are missing. This result cannot be submitted','Direct API calls cannot bypass the evidence check');
select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='finish'));
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.review_submission((select (result->'candidates'->0->>'id')::uuid from results where name='finish'),true,'Verified ending');
select throws_ok($$select public.review_submission((select (result->'candidates'->0->>'id')::uuid from results where name='finish'),true,'Again')$$,'P0001','Pending submission not found','Repeated approvals cannot produce duplicate notifications');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(jsonb_array_length(public.my_submission_notifications()),1,'Approval creates one owner notification');
select is(public.my_submission_notifications()->0->>'decision','approved','Approval notification has the verified decision');
select is(public.my_submission_notifications()->0->>'note','Verified ending','Reviewer note reaches the solver');
insert into results values('second',public.record_online_attempt(public.begin_attempt('bbbbbbbb-bbbb-4bbb-8bbb-bbbbbbbbbbbb'),'{"format":"fto-replay-v1","size":3,"complete":true,"solveMs":40,"events":[]}'));
select public.submit_leaderboard((select (result->'candidates'->0->>'id')::uuid from results where name='second'));
select set_config('request.jwt.claim.sub','33333333-3333-4333-8333-333333333333',true);
select public.review_submission((select (result->'candidates'->0->>'id')::uuid from results where name='second'),false,'Ending cannot be verified');
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select is(public.my_submission_notifications()->0->>'decision','rejected','Rejection appears as the latest notification');
select is(public.my_submission_notifications()->0->>'note','Ending cannot be verified','Rejection reason is preserved');
select throws_ok($$select * from public.submission_notifications$$,'42501',null,'Clients cannot read notification tables directly');
select throws_ok($$select public.leaderboard_evidence_available('[]','ao5')$$,'42501',null,'Internal recording evidence checks are not public RPCs');
select set_config('request.jwt.claim.sub','22222222-2222-4222-8222-222222222222',true);
select is(public.my_submission_notifications(),'[]'::jsonb,'Other accounts cannot read the solver notifications');
select public.mark_submission_notifications_read(array[1,2]::bigint[]);
set local role postgres;
select is((select count(*)::integer from public.submission_notifications where read_at is not null),0,'Other accounts cannot mark the solver notifications read');
set local role authenticated;
select set_config('request.jwt.claim.sub','11111111-1111-4111-8111-111111111111',true);
select public.mark_submission_notifications_read(array(select (n->>'id')::bigint from jsonb_array_elements(public.my_submission_notifications()) n));
select is((select bool_and(n->>'read_at' is not null) from jsonb_array_elements(public.my_submission_notifications()) n),true,'Read state survives on the server');
set local role anon;
select throws_ok($$select public.my_submission_notifications()$$,'42501',null,'Anonymous users cannot read notifications');
set local role postgres;
insert into public.submission_notifications(user_id,metric,ms,decision,created_at) select '11111111-1111-4111-8111-111111111111','single',100,'approved',now()-n*interval '1 second' from generate_series(1,55) n;
insert into public.submission_notifications(user_id,metric,ms,decision,created_at) values('11111111-1111-4111-8111-111111111111','single',100,'rejected',now()-interval '91 days');
select public.prune_recordings();
select is((select count(*)::integer from public.submission_notifications),50,'Notification history is bounded to 50 per account');
select is((select count(*)::integer from public.submission_notifications where created_at<now()-interval '90 days'),0,'Hourly recording cleanup also expires old notifications');
select * from finish();rollback;
